body{background:#fcfcfc;color:#171717;font:15px/1.75 Arial,system-ui,sans-serif}header{background:#fcfcfc;border-bottom:1px solid #ddd;padding:15px 5vw;display:flex;gap:20px;align-items:center;justify-content:space-between;font-size:10px;letter-spacing:1px}header a{color:#202020;text-decoration:none}header b{margin-left:20px;color:#907036}main{max-width:828px;margin:auto;padding:34px 30px}article{max-width:none;margin:0}#faithful-report{width:100%;max-width:100%}#faithful-report img{max-width:100%;height:auto}#faithful-report button[aria-label^="Open "],#faithful-report button[aria-label*="favoris"]{display:none!important}#faithful-report [role=radio]{cursor:pointer}#faithful-report svg{max-width:100%}#faithful-report h1,#faithful-report h2,#faithful-report h3{border:0;padding-left:0}#extras-storage{display:contents}.site-extras{grid-column:1/-1;font:400 14px/1.6 Arial,sans-serif;letter-spacing:normal}.crypto-band{color:#e7edf5;margin:12px 0 18px;font:13px/1.6 Arial,sans-serif}.crypto-band strong{color:#f3dfac}.edition-picker{margin:15px 0 24px;max-width:none}.edition-picker label{color:#526361}.edition-picker select{color:#222;background:#f7f7f7;border:1px solid #ccc}.edition-picker small{color:#666}#faithful-report button[aria-haspopup]{cursor:default}.edition-note{font-size:12px;color:#666;margin-top:30px}.edition-note a{color:#886f38}#crypto-distribution{color:#222}.infographic{color:#dce5eb}.site-extras select{font-size:14px}.faithful-source-img{border-radius:16px}@media(max-width:650px){main{padding:24px 18px}header{flex-wrap:wrap}header div{order:3;width:100%}#faithful-report *{grid-template-columns:minmax(0,1fr)!important;min-width:0;max-width:100%}#faithful-report table{display:table!important;width:100%!important}#faithful-report td,#faithful-report th{padding:7px!important;font-size:12px!important}#faithful-report img{height:auto!important}#faithful-report [style*="flex-direction: row"]{flex-wrap:wrap!important}}@media print{header,.site-extras,.edition-note,#crypto-distribution{display:none}}
